# 循环与else示例
for i in range(3):
    print(i)
else:
    print('Loop ended')
# 输出 0 1 2 Loop ended

# 可变参数示例
def func(*args, **kwargs):
    print(args, kwargs)
func(1,2,3,a=4,b=5)

# 递归阶乘
def factorial(n):
    return 1 if n<=1 else n*factorial(n-1)
print(factorial(5))  # 120

# 函数作为对象
def f1(): print('11', end=' ')
def f2(): print('22', end=' ')
def f3(): print('33', end=' ')
for f in [f1,f2,f3]: f()
# 输出: 11 22 33
